source2='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    line = max((c for c in counts if c != bg), key=lambda c: counts[c])
    fill = 4
    out = [row[:] for row in grid]
    # Fill only fully outlined rectangular cavities.
    for top in range(h-2):
        for bottom in range(top+2, h):
            for left in range(w-2):
                for right in range(left+2, w):
                    if any(grid[top][x] != line or grid[bottom][x] != line for x in range(left, right+1)):
                        continue
                    if any(grid[y][left] != line or grid[y][right] != line for y in range(top, bottom+1)):
                        continue
                    if all(grid[y][x] == bg for y in range(top+1, bottom) for x in range(left+1, right)):
                        for y in range(top+1, bottom):
                            for x in range(left+1, right):
                                out[y][x] = fill
    return out
'''
